import { chromium } from 'playwright';

const OUT = '/tmp/claude-1000/-home-runner-workspace/48ba60f3-59cf-44b6-bbb6-81892778133a/scratchpad';
const BASE = 'http://localhost:5000';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.on('console', m => { if (m.type() === 'error') console.log('[console.error]', m.text()); });

// Retail checkout
await page.goto(`${BASE}/checkout/90210`, { waitUntil: 'networkidle' });
await page.waitForTimeout(1200);
await page.screenshot({ path: `${OUT}/retail.png` });

// Find payable property + trades tokens by probing the in-page mock fetch
const tokens = await page.evaluate(async () => {
  const found = { property: null, trades: null };
  for (let i = 5000; i < 5120 && !found.property; i++) {
    try { const r = await fetch(`/api/checkout/resolve/inv_${i}`); if (r.ok) { const j = await r.json(); if (!j.alreadyPaid) found.property = `inv_${i}`; } } catch {}
  }
  for (let i = 7000; i < 7120 && !found.trades; i++) {
    try { const r = await fetch(`/api/checkout/resolve/job_${i}`); if (r.ok) { const j = await r.json(); if (!j.alreadyPaid) found.trades = `job_${i}`; } } catch {}
  }
  return found;
});
console.log('tokens:', JSON.stringify(tokens));

if (tokens.property) {
  await page.goto(`${BASE}/r/${tokens.property}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/property.png` });
  // expand card panel
  const link = page.getByText(/enter credit card/i);
  if (await link.count()) { await link.first().click(); await page.waitForTimeout(800); await page.screenshot({ path: `${OUT}/property-card-open.png` }); }
}
if (tokens.trades) {
  await page.goto(`${BASE}/r/${tokens.trades}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/trades.png` });
}
await browser.close();

