23	class CheckoutErrorBoundary extends Component<{ children: ReactNode }, { hasError: boolean }> {
24	  constructor(props: { children: ReactNode }) {
25	    super(props);
26	    this.state = { hasError: false };
27	  }
28	  static getDerivedStateFromError() { return { hasError: true }; }
