52	function detectInAppBrowser(): { isInApp: boolean; isAndroid: boolean; isIOS: boolean } {
53	  const ua = navigator.userAgent || "";
54	  const isAndroid = /Android/i.test(ua);
55	  const isIOS = /iPhone|iPad|iPod/i.test(ua);
56	  const isInApp =
57	    /FBAN|FBAV|Instagram|Twitter|Line|WeChat|Snapchat|TikTok|LinkedIn|Pinterest|Tumblr|Reddit|Bytedance/i.test(ua) ||
58	    (isAndroid && /wv\)/i.test(ua)) ||
59	    (/\bMobile\b/.test(ua) && !/Chrome|CriOS|FxiOS|Safari/i.test(ua) && (isAndroid || isIOS));
60	  return { isInApp, isAndroid, isIOS };
61	}
62	
63	function loadScript(src: string): Promise<void> {
64	  return new Promise((resolve, reject) => {
65	    if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
66	    const s = document.createElement("script");
67	    s.src = src; s.async = true;
68	    s.onload = () => resolve();
69	    s.onerror = () => reject(new Error(`Failed: ${src}`));
70	    document.head.appendChild(s);
71	  });
