455	  const realFetch = window.fetch.bind(window);
456	
457	  window.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
458	    const rawUrl = typeof input === 'string' ? input : input instanceof URL ? input.href : (input as Request).url;
459	    const method = (init?.method || (input instanceof Request ? input.method : 'GET')).toUpperCase();
